// is the same as the function f(c,d) = NOT(c XOR d), so we can use a 2-to-1 mux per input,
// and a 4-to-1 mux to connect all the partial functions together.
module TopModule(input c, d, output [3:0] mux_in);
    wire a = c ^ d;
    wire b = c & (~d);
    wire [3:0] partial_muxes = {a, b, a, b};
    TRANSLATED_4TO1_MUX mux(.a(a), .b(b), .s(partial_muxes));
endmodule

