// The Karnaugh map for the function f(a,b) = ab + a'b' + a + b' (the sum of
// the 4 basic terms) is:
//
//      ab
//  cd  00  01  11  10
//  00 | 0 | 0 | 0 | 1 |
//  01 | 1 | 0 | 0 | 0 | the 4-to-1 mux selector is (a xor b, a and not b)
//  11 | 1 | 0 | 1 | 1 |
//  10 | 1 | 0 | 0 | 1 |
//
// Re-written as a 4-to-1 mux with two 2-to-1 multiplexers (one for each
// term of the sum), this forms the final circuit:
//
//  ab + a'b' + a + b' = NOT(a AND b) AND a OR NOT(a AND NOT b) AND a OR b'
//  abbreviated as: ((NOT a) AND b) OR (a AND NOT b) OR b'
//
// This is the same function as the Karnaugh map, so the two-to-1 multiplexers
// together form the full 4-to-1 mux circuit.
module TopModule(input c, d, output reg [3:0] mux_in);
    wire a = c;
    wire b = d;
    wire [3:0] mux0_in = a & b;
    wire [3:0] mux1_in = a ^ b;
    always @(*) begin
        mux_in = {(~mux0_in & mux1_in) | (a & ~b) | b};
    end
endmodule

